(x, y, t) => {
  const cx = 240, cy = 120;
  const w1 = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w2 = Math.cos(y*0.022-t*0.28)*14 + Math.sin(x*0.016+t*0.38)*11;
  const w3 = Math.sin((x+y)*0.008+t*0.15)*20 + Math.cos((x-y)*0.01-t*0.12)*15;
  const sx = x+w1+w3*0.5, sy = y+w2+w3*0.5;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65+1)*55, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*70, 200+Math.sin(t*0.75+4)*65, 0.065, 2.4, 1.05]
  ];
  let aS=0, iS=0, hS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    const wave2 = Math.sin(d*f*1.618 - t*sp*0.618 + 0.5);
    aS += (wave + wave2*0.3)*w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5)*w;
    hS += Math.sin(d*f*0.5 - t*sp*0.4 + 2.8)*w*0.5;
  }
  const n = 8;
  aS /= n; iS /= n; hS /= n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07+Math.sin(sy*0.05+t)*3+t*1.3)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.08-ang*2+t*0.9)*0.2;
  const voronoi = (() => {
    let md = 999, md2 = 999;
    for (let i = 0; i < 7; i++) {
      const px = (Math.sin(i*2.399+t*0.2)*0.5+0.5)*480;
      const py = (Math.cos(i*2.399+t*0.15)*0.5+0.5)*240;
      const d = Math.sqrt((sx-px)**2+(sy-py)**2);
      if (d < md) { md2 = md; md = d; } else if (d < md2) md2 = d;
    }
    return Math.sin((md2-md)*0.3)*0.3;
  })();
  const rd1 = aS - iS*0.7 + bg*0.3 + spiral;
  const rd2 = Math.tanh(rd1*1.8) - Math.tanh(rd1*-1.2)*0.3;
  const reaction = Math.tanh((rd2 + voronoi + hS*0.15)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+sy*0.25+t*3)*Math.sin(sx*0.25-sy*0.3-t*2.5)*0.08;
  const blend = reaction*0.6 + cell*0.25 + micro*0.15;
  const v = blend*0.5+0.5;
  const hueShift = hS*0.12;
  const pal = [
    [12,15,75],[18,50,120],[20,95,135],[25,145,125],
    [160,190,80],[220,185,55],[225,130,65],[195,70,75],
    [130,35,85],[60,18,70],[12,15,75]
  ];
  const idx = Math.max(0, Math.min((pal.length-1), (v+hueShift)*(pal.length-1)));
  const i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge = Math.abs(reaction)>0.65?1.12:1.0;
  const glow = Math.max(0, reaction-0.5)*0.4;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*60)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*40)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*20)|0)
  ];
}
